function bindView(){if(route==='docs'){const filter=$('#documentFilter');if(filter)filter.addEventListener('input',()=>{documentFilter=filter.value;$('#docRows').innerHTML=docRows();});const search=$('#fullSearch');if(search)search.addEventListener('keydown',e=>{if(e.key==='Enter'){searchQuery=search.value;$('#searchResults').innerHTML=searchResults(searchQuery);}});const drop=$('#dropzone');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('dragging');});drop.addEventListener('dragleave',()=>drop.classList.remove('dragging'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragging');importFiles([...e.dataTransfer.files]);});}}if(route==='behavior')$$('input[type=range]').forEach(el=>el.addEventListener('input',()=>{$('#'+el.id+'Out').textContent=el.value;}));const status={carbon:'#carbonStatus',behavior:'#behaviorStatus',finance:'#financeStatus',policy:'#policyStatus'}[route];if(status)$$('#main input,#main textarea,#main select').forEach(el=>el.addEventListener('input',()=>{const s=$(status);if(s){s.classList.add('dirty');s.textContent='参数已修改，尚未保存；右侧显示上次结果。';}}));}
let downloadURL='';
function download(name,content,type='application/json'){
 if(downloadURL)URL.revokeObjectURL(downloadURL);
 const blob=new Blob([content],{type});downloadURL=URL.createObjectURL(blob);
 $('#downloadReady')?.remove();const card=document.createElement('div');card.id='downloadReady';card.className='download-ready';
 const label=document.createElement('div');label.className='download-label';label.textContent='文件已生成 · '+name;
 const a=document.createElement('a');a.id='lastDownload';a.className='button lime small';a.href=downloadURL;a.download=name;a.textContent='下载文件';
 const preview=document.createElement('button');preview.className='button outline small';preview.textContent='预览内容';preview.onclick=()=>{modal(name,`<p class="hint">如浏览器没有弹出下载，可复制下方完整内容保存。字符数：${String(content).length}</p><textarea id="exportPreview" readonly style="width:100%;min-height:320px;font:11px/1.8 monospace;padding:12px;border:1px solid #dfe6d5;border-radius:9px" aria-label="导出文件完整内容">${esc(content)}</textarea>`,btn('复制完整内容','copy-export','outline'));};
 const close=document.createElement('button');close.className='close';close.textContent='×';close.setAttribute('aria-label','关闭下载提示');close.onclick=()=>card.remove();
 card.append(label,preview,a,close);document.body.append(card);a.click();toast('已生成下载文件：'+name);
}
function sourceView(id,page,extract=false){const doc=project().docs.find(x=>x.id===id);if(!doc)throw Error('关联资料不存在，请重新选择');const p=doc.pages.find(x=>x.page===Number(page))||doc.pages[0];const candidates=extract?C.candidates(doc):[];$('#drawer').hidden=false;$('#drawer').innerHTML=`<div class="drawer-panel"><div class="dialog-head"><div><div class="eyebrow">SOURCE & EVIDENCE</div><h2>${esc(doc.title)}</h2></div><button class="close" data-action="close-source" aria-label="关闭资料">×</button></div><div class="row between">${tag(doc.kind)}${safeURL(doc.url)?`<a class="button outline small" href="${esc(safeURL(doc.url))}${/\.pdf$/i.test(doc.url)?'#page='+p.page:''}" target="_blank" rel="noopener">打开原始来源 ↗</a>`:tag('浏览器本地文本','gray')}</div><p class="hint" style="margin-top:16px">${doc.kind.includes('摘编')?'当前为案例摘编。页码指向原文件，摘编不能替代原文核对。':'下方为导入文件提取的文字。表格列序可能错位，关键数字需回原文核对。'}</p><div class="row" style="margin-top:17px"><span class="hint">定位页</span><select id="sourcePage" class="searchbox" style="width:150px" data-id="${id}">${doc.pages.map(x=>`<option value="${x.page}" ${x.page===p.page?'selected':''}>第 ${x.page} 页</option>`).join('')}</select><button class="text-button" data-action="extract" data-id="${id}">提取数字候选句 →</button></div><div class="source-text">${esc(p.text||'本页未提取到文字，可能是扫描图像。')}</div>${extract?`<div class="spacer"></div><h3>候选句 ${candidates.length} 条</h3><p class="hint">规则识别数字与单位，不自动认定为事实。</p>${candidates.map(c=>`<div class="candidate"><div class="row between">${tag(c.type,c.type==='政策目标'?'orange':'gray')}<span class="hint">第${c.page}页</span></div><p>${esc(c.text)}</p><button class="text-button" data-action="candidate-fact" data-id="${id}" data-candidate="${c.id}">人工核对并建立字段 →</button></div>`).join('')||empty('没有识别到候选句','可以通过经营事实表手动添加字段。')}`:''}<div class="divider"></div>${btn('从当前研究移除此资料','remove-source','danger small',`data-id="${id}"`)}<p class="hint" style="margin-top:12px">不会删除你的电脑原文件。</p></div>`;$('#sourcePage').addEventListener('change',e=>sourceView(id,e.target.value,extract));}
function factModal(id,candidate){const p=project(),f=p.facts.find(f=>f.id===id)||{id:uid(),label:'',value:'',unit:'',period:'',scope:'',location:candidate?'第'+candidate.page+'页':'',sourceId:candidate?.sourceId||p.docs[0]?.id||'',reviewed:false};modal(id?'编辑经营事实':'新增经营事实',`${candidate?`<div class="alert">候选原句：${esc(candidate.text)}<br>请手工核对字段、数值和期间，政策目标应在名称中注明。</div>`:''}${textfield('指标名称','factLabel',f.label)}<div class="field-grid">${textfield('数值','factValue',f.value)}${textfield('单位','factUnit',f.unit)}${textfield('期间','factPeriod',f.period)}${textfield('地区与业务范围','factScope',f.scope)}</div><label class="field"><span>资料来源</span><select id="factSource"><option value="">手动输入（待补来源）</option>${p.docs.map(d=>`<option value="${d.id}" ${f.sourceId===d.id?'selected':''}>${esc(d.title)}</option>`).join('')}</select></label>${textfield('原文定位','factLocation',f.location)}<label class="check"><input type="checkbox" id="factReviewed" ${f.reviewed?'checked':''}>已对照原始材料核对，不把假设或政策目标写成已实现业绩。</label>`,btn('保存字段','save-fact','',`data-id="${f.id}"`));}
function projectModal(edit=false){const p=project();modal(edit?'编辑研究范围':'新建研究',`${textfield('研究名称','pTitle',edit?p.profile.title:'','例如：城市出行政策影响研究')}<div class="field-grid">${textfield('研究城市','pCity',edit?p.profile.city:'')}${textfield('研究公司','pCompany',edit?p.profile.company:'')}</div>${textarea('要回答的问题','pQuestion',edit?p.profile.question:'',3)}${!edit?'<label class="check"><input type="checkbox" id="pSample">载入常州—永安行案例资料与基准（会使用对应案例范围）</label><p class="hint">空白研究不含案例事实；模型参数保留假设演示值，收入基准默认为0。</p>':''}`,btn('保存研究','save-project','',`data-edit="${edit}"`));}
function readCarbon(){return $$('#carbonRows .carbon-row[data-row]').map(el=>{const r={};el.querySelectorAll('[data-key]').forEach(input=>{if(input.dataset.key==='name')r.name=input.value;else{if(!input.value.trim())throw Error('请填写所有出行数值');r[input.dataset.key]=Number(input.value);}});return r;});}
function readBehavior(){return {initial:safeNum('#bInitial')/100,incentive:safeNum('#bIncentive'),costSaving:safeNum('#bSaving'),extraMinutes:safeNum('#bMinutes'),timeValue:safeNum('#bTime'),comfort:safeNum('#bComfort'),carbonPrice:safeNum('#bPrice'),carbonKg:safeNum('#bCarbon'),response:safeNum('#bResponse'),rounds:safeNum('#bRounds')};}
function readFinance(){return {baseline:safeNum('#fBaseline'),paidOrdersWan:safeNum('#fPaid'),freeOrdersWan:safeNum('#fFree'),price:safeNum('#fPrice'),cost:safeNum('#fCost',true),compensation:safeNum('#fComp'),contractVerified:$('#fVerified').checked,contractRef:$('#fRef').value,capex:safeNum('#fCapex'),workingCapital:safeNum('#fWorking'),otherCash:safeNum('#fOther')};}
function reportText(){const p=project(),t=currentReport||p.reports[0]?.text;if(!t)throw Error('请先生成研究报告');return t;}
function exportReport(html){const text=reportText();if(!html){download('绿行智研_研究报告.md',text,'text/markdown;charset=utf-8');return;}download('绿行智研_研究报告.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>绿行智研研究报告</title><style>body{max-width:840px;margin:50px auto;padding:25px;font:16px/1.9 SimSun,serif;color:#263b30}h1{font-size:27px;border-bottom:2px solid #335c45;padding-bottom:20px}h2{font-size:20px;margin-top:30px}p{overflow-wrap:anywhere}@media print{body{margin:0}}</style>${markdownHTML(text)}</html>`,'text/html;charset=utf-8');}
async function importFiles(files){if(busy){toast('已有文件正在解析，请稍候');return;}if(!files.length)return;const target=project();if(target.docs.length+files.length>60)throw Error('单个研究最多60份资料');busy=true;let imported=0;const status=msg=>{const el=$('#uploadStatus');if(el)el.innerHTML='<span class="spinner"></span>'+esc(msg);};for(const file of files){try{status('正在解析 '+file.name);if(file.size>25*1024*1024)throw Error('超过25MB限制');const ext=file.name.split('.').pop().toLowerCase();let pages=[];if(ext==='pdf'){const lib=await import('./vendor/pdf.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',location.href).href;const task=lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),cMapUrl:new URL('./vendor/cmaps/',location.href).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/standard_fonts/',location.href).href,wasmUrl:new URL('./vendor/wasm/',location.href).href,isEvalSupported:false});let pdf;try{pdf=await task.promise;if(pdf.numPages>300)throw Error('PDF超过300页，请先按章节拆分');for(let page=1;page<=pdf.numPages;page++){status(file.name+' · 第 '+page+' / '+pdf.numPages+' 页');const p=await pdf.getPage(page),data=await p.getTextContent();let text='';for(const item of data.items)if('str'in item)text+=item.str+(item.hasEOL?'\n':' ');pages.push({page,text:text.trim()});p.cleanup();}}finally{await task.destroy();}if(pages.every(p=>p.text.length<5))throw Error('未发现可用文本：扫描PDF需先进行OCR');}else if(['txt','md','csv','json'].includes(ext)){const text=await file.text();if(!text.trim())throw Error('文件为空');if(text.includes('\uFFFD')&&text.split('\uFFFD').length>10)throw Error('编码不兼容，请另存为UTF-8文本');pages=text.split('\f').map((text,i)=>({page:i+1,text}));}else throw Error('不支持该格式');const characters=pages.reduce((n,p)=>n+p.text.length,0);if(characters>2000000)throw Error('文本超过200万字符，请拆分后导入');const hash=C.hash(pages.map(p=>p.text).join('\n'));if(target.docs.some(d=>d.hash===hash)){toast(file.name+'：已存在相同文本');continue;}const doc={id:uid(),title:file.name.replace(/\.[^.]+$/,''),kind:ext==='pdf'?'PDF解析':'文本资料',date:new Date().toISOString().slice(0,10),pages,characters,hash,fileName:file.name,url:''};target.docs.push(doc);imported++;await persist();}catch(e){toast(file.name+'：'+e.message,true);}}busy=false;$('#fileImport').value='';if(project().id===target.id&&route==='docs')render();toast('导入完成：新增 '+imported+' 份资料');}
const guide=[['docs','先打开一份资料','查看来源与页码，提取候选句并人工核对。'],['policy','明确政策作用路径','核对措施、需求变化、结算关系与待补依据。'],['carbon','算清减排差额','调整次数与里程，点击“计算并保存”。'],['behavior','观察激励如何影响选择','比较不同激励曲线，保留模型假设。'],['finance','检验收入兑现条件','切换付费、免费和补偿情景，观察收入与成本。'],['report','交付一份完整底稿','生成报告，检查依据并导出研究包。'],['proof','查看研究与功能测试','查阅公开研究、实现范围，并现场运行检查。']];
function renderGuide(){$('#guideFloating')?.remove();if(guideStep<0)return;const item=guide[guideStep],el=document.createElement('div');el.id='guideFloating';el.className='guide-floating';el.innerHTML=`<div><b>${guideStep+1} / ${guide.length}　${item[1]}</b><p>${item[2]}</p></div>${btn(guideStep===guide.length-1?'完成导览':'下一步 →','guide-next','lime small')}<button class="close" data-action="guide-close" aria-label="退出导览">×</button>`;document.body.append(el);}
const actions={
 'copy-export':async()=>{await navigator.clipboard.writeText($('#exportPreview').value);toast('完整内容已复制');},
 'close':closeDialog,'close-source':()=>{$('#drawer').hidden=true;},
 'start':()=>go('docs'),'doc-tab':el=>{docTab=el.dataset.id;render();},
 'import':()=>$('#fileImport').click(),'paste':()=>modal('粘贴一份研究资料',textfield('资料标题','pasteTitle','')+textfield('来源链接（可选）','pasteUrl','')+textarea('资料正文','pasteText','',9),btn('保存到资料库','save-paste')),
 'save-paste':()=>{const title=$('#pasteTitle').value.trim(),text=$('#pasteText').value.trim(),url=$('#pasteUrl').value.trim();if(!title||!text)throw Error('请填写标题与正文');if(text.length>2000000)throw Error('文本过长，请拆分');if(url&&!safeURL(url))throw Error('来源链接须为 http 或 https');project().docs.push({id:uid(),title,kind:'人工录入',url,date:new Date().toISOString().slice(0,10),pages:[{page:1,text}],hash:C.hash(text)});persist();closeDialog();go('docs');toast('资料已保存');},
 'source':el=>sourceView(el.dataset.id,el.dataset.page),'extract':el=>sourceView(el.dataset.id,el.dataset.page,true),
 'remove-source':el=>{const d=project().docs.find(x=>x.id===el.dataset.id);modal('移除这份资料？',`<p class="small-text">仅移除当前研究中的“${esc(d.title)}”。关联事实会标为待复核，电脑原文件不受影响。</p>`,btn('取消','close','outline')+btn('确认移除','confirm-remove-source','danger',`data-id="${d.id}"`));},
 'confirm-remove-source':el=>{const p=project(),id=el.dataset.id;p.docs=p.docs.filter(d=>d.id!==id);p.facts.forEach(f=>{if(f.sourceId===id){f.reviewed=false;f.sourceId='';f.source=(f.source||'')+'（关联资料已移除）';}});if(p.policy.sourceId===id){p.policy.sourceId='';p.policy.confirmed=false;}p.tracking?.forEach(t=>{if(t.sourceId===id){t.sourceId='';t.status='pending';}});persist();closeDialog();$('#drawer').hidden=true;render();toast('已从当前研究移除，可重新导入原文件');},
 'query':el=>{searchQuery=el.dataset.query;$('#fullSearch').value=searchQuery;$('#searchResults').innerHTML=searchResults(searchQuery);},
 'full-search':()=>{searchQuery=$('#fullSearch').value;$('#searchResults').innerHTML=searchResults(searchQuery);},
 'search':()=>{modal('搜索资料与事实',`<input id="globalQuery" class="searchbox" placeholder="例如：常州、免费、2934.75" aria-label="全局搜索关键词"><div class="suggestions">${['常州','免费','收入'].map(q=>`<button data-action="global-query" data-query="${q}">${q}</button>`).join('')}</div><div id="globalResults">${empty('搜索当前研究的全部文本','输入关键词后按回车')}</div>`);$('#globalQuery').focus();$('#globalQuery').addEventListener('keydown',e=>{if(e.key==='Enter')$('#globalResults').innerHTML=searchResults($('#globalQuery').value);});},
 'global-query':el=>{$('#globalQuery').value=el.dataset.query;$('#globalResults').innerHTML=searchResults(el.dataset.query);},
 'add-fact':()=>factModal(),'edit-fact':el=>factModal(el.dataset.id),'candidate-fact':el=>{const d=project().docs.find(d=>d.id===el.dataset.id),c=C.candidates(d).find(c=>c.id===el.dataset.candidate);factModal(null,c);},
 'save-fact':el=>{const p=project(),label=$('#factLabel').value.trim(),value=$('#factValue').value.trim(),sourceId=$('#factSource').value,reviewed=$('#factReviewed').checked;if(!label||!value)throw Error('请填写指标名称与数值');if(reviewed&&(!sourceId||!$('#factLocation').value.trim()))throw Error('标记已核对前，请关联来源与定位');const f={id:el.dataset.id,label,value,unit:$('#factUnit').value,period:$('#factPeriod').value,scope:$('#factScope').value,location:$('#factLocation').value,sourceId,source:p.docs.find(d=>d.id===sourceId)?.title||'手动输入',reviewed};const index=p.facts.findIndex(x=>x.id===f.id);if(index<0)p.facts.push(f);else p.facts[index]=f;persist();closeDialog();$('#drawer').hidden=true;docTab='facts';go('docs');toast('事实字段已保存');},
 'policy-source':()=>sourceView($('#policySource').value),
 'save-policy':()=>{const p=project();const v={measure:$('#policyMeasure').value.trim(),effect:$('#policyEffect').value.trim(),gap:$('#policyGap').value.trim(),sourceId:$('#policySource').value,confirmed:$('#policyConfirmed').checked};if(!v.measure||!v.effect)throw Error('请填写政策措施与影响路径');if(v.confirmed&&!v.sourceId)throw Error('请先关联政策资料');p.policy=v;record('政策路径复核',v,{confirmed:v.confirmed});render();toast('政策分析已保存');},
 'carbon-template':()=>download('出行替代模板.csv',C.safeCSV([['方式','次数','单次公里','基准因子','情景因子'],['驾车转骑行',100,5,.12,.02]]),'text/csv;charset=utf-8'),
 'import-carbon':()=>$('#csvImport').click(),
 'add-carbon':()=>{const p=project();p.carbonRows=readCarbon();p.factorNote=$('#factorNote').value;p.carbonRows.push({name:'新增方式',trips:0,km:0,base:.12,green:0});p.carbonResult=null;persist();render();},
 'remove-carbon':el=>{const p=project();if(p.carbonRows.length<=1)throw Error('至少保留一条记录');p.carbonRows=readCarbon();p.carbonRows.splice(Number(el.dataset.index),1);p.factorNote=$('#factorNote').value;p.carbonResult=null;persist();render();},
 'calculate-carbon':()=>{const start=performance.now(),p=project(),rows=readCarbon(),r=C.carbon(rows),note=$('#factorNote').value.trim();if(!note)throw Error('请填写因子来源与假设边界');p.carbonRows=rows;p.carbonResult=r;p.factorNote=note;if(p.carbonLinked){p.behaviorInputs.carbonKg=r.perTripKg;p.behaviorResult=null;if(p.orderMapping)p.financeResult=null;}record('碳核算',{rows,factorNote:note},r,start);render();toast('碳核算已保存：'+fmt(r.reductionKg)+' kg CO₂e'+(p.carbonLinked?'；关联行为情景需重算':''));},
 'export-carbon':()=>{const p=project(),r=p.carbonResult;if(!r)throw Error('请先计算并保存碳核算');download('绿行智研_碳核算底稿.csv',C.safeCSV([['方式','次数','单次公里','基准因子','情景因子','基准kg','情景kg','减排kg'],...r.items.map(x=>[x.name,x.trips,x.km,x.base,x.green,x.baselineKg,x.scenarioKg,x.reductionKg]),['合计','','','','',r.baselineKg,r.scenarioKg,r.reductionKg],['因子说明',p.factorNote]]),'text/csv;charset=utf-8');},
 'carbon-to-behavior':()=>{const p=project();if(!p.carbonResult)throw Error('请先计算并保存碳核算');p.carbonLinked=true;p.behaviorInputs.carbonKg=p.carbonResult.perTripKg;p.behaviorResult=null;if(p.orderMapping)p.financeResult=null;persist();go('behavior');toast('已带入每次减排差额，请核对行为模型的适用范围');},
 'load-carbon':()=>{const r=project().carbonResult;if(!r)throw Error('请先完成碳核算');$('#bCarbon').value=r.perTripKg;$('#behaviorStatus').textContent='已载入每次减排差额，重新运行后保存。';},
 'calculate-behavior':()=>{const start=performance.now(),p=project(),v=readBehavior(),r=C.behavior(v);if(p.carbonLinked&&v.carbonKg!==p.carbonResult?.perTripKg)p.carbonLinked=false;p.behaviorInputs=v;p.behaviorResult=r;if(p.orderMapping){p.financeInputs.paidOrdersWan=Number((p.orderMapping.trips*r.change*p.orderMapping.share/100/10000).toFixed(4));p.financeResult=null;}record('行为情景模拟',v,r,start);render();toast('情景已保存；这是条件推演，不是实际订单预测');},
 'map-orders':()=>{if(!project().behaviorResult)throw Error('请先运行并保存行为模拟');modal('将行为情景映射到订单假设',`<p class="small-text muted">占比变化不等于企业订单增长。这里额外设置总出行量和业务承接比例，得到一个显式假设，供财务敏感性分析。</p><div class="spacer"></div>${input('研究期总出行次数','mapTrips',1000000,'次','min="0"')}${input('目标业务承接比例','mapShare',20,'%','min="0" max="100"')}<p class="hint">订单变化 = 总出行次数 × 绿色出行占比变化 × 承接比例。该假设只更新收费订单字段，必须另行核对收费性质。</p>`,btn('带入财务参数','confirm-map'));},
 'confirm-map':()=>{const p=project(),trips=safeNum('#mapTrips'),share=safeNum('#mapShare');if(trips<0||share<0||share>100)throw Error('次数须非负，比例须在0—100之间');const orders=Number((trips*p.behaviorResult.change*share/100/10000).toFixed(4));p.orderMapping={trips,share};p.financeInputs.paidOrdersWan=orders;p.financeResult=null;record('行为到订单的假设映射',{trips,share,change:p.behaviorResult.change},{paidOrdersWan:orders});closeDialog();go('finance');toast('已带入假设订单，尚未计算收入');},
 'preset':el=>{const p=project(),v={...p.financeInputs,paidOrdersWan:30,freeOrdersWan:0,price:2.16,cost:1,compensation:0,contractVerified:false,contractRef:'',capex:0,workingCapital:0,otherCash:0};if(el.dataset.id!=='paid'){v.paidOrdersWan=0;v.freeOrdersWan=30;}if(el.dataset.id==='comp'){v.compensation=12;v.contractVerified=true;v.contractRef='演示假设：有效合同服务收入增量12万元，且满足当期收入确认条件；不是实际合同。';}p.financeInputs=v;p.financeResult=null;persist();render();toast('已载入参数，点击计算并保存');},
 'calculate-finance':()=>{const start=performance.now(),p=project(),v=readFinance(),r=C.finance(v);if(p.orderMapping&&v.paidOrdersWan!==p.financeInputs.paidOrdersWan)p.orderMapping=null;p.financeInputs=v;p.financeResult=r;record('财务情景测算',v,r,start);render();toast('财务情景已保存，收入增量 '+fmt(r.deltaRevenueWan)+' 万元');},
 'to-report':()=>go('report'),
 'export-finance':()=>{const p=project(),r=p.financeResult;if(!r)throw Error('请先运行财务测算');download('绿行智研_财务测算.csv',C.safeCSV([['指标','数值','单位'],['基准收入',p.financeInputs.baseline,'万元'],['收费订单变化',p.financeInputs.paidOrdersWan,'万笔'],['免费订单增加',p.financeInputs.freeOrdersWan,'万笔'],['单价',p.financeInputs.price,'元/笔'],['边际成本',p.financeInputs.cost,'元/笔'],['收入增量',r.deltaRevenueWan,'万元'],['经营贡献',r.contributionWan,'万元'],['扣所填现金支出后差额',r.cashAfterInputsWan,'万元'],['提示','情景假设，不等于净利润或完整自由现金流','']]),'text/csv;charset=utf-8');},
 'save-conclusion':()=>{project().conclusion=$('#reportConclusion').value;persist();toast('结论已保存；重新生成报告后进入新版本');},
 'generate-report':()=>{const p=project();if($('#reportConclusion'))p.conclusion=$('#reportConclusion').value;if(!p.docs.length)throw Error('请先添加研究资料');const start=performance.now();currentReport=C.report(p);const item={id:uid(),createdAt:new Date().toISOString(),text:currentReport,inputHash:C.hash(JSON.stringify([p.profile,p.policy,p.carbonResult,p.behaviorResult,p.financeResult,p.facts,p.conclusion]))};p.reports.unshift(item);p.reports=p.reports.slice(0,20);record('报告编排',{inputHash:item.inputHash},{reportId:item.id,characters:currentReport.length},start);render();toast('已生成新报告版本');},
 'view-report':el=>{currentReport=project().reports.find(r=>r.id===el.dataset.id)?.text||'';render();toast('正在查看已保存版本，不是当前参数的自动重算');},
 'export-report-html':()=>exportReport(true),'export-report-md':()=>exportReport(false),'print-report':()=>{reportText();window.print();},
 'export-bundle':()=>{const p=project();download('绿行智研_完整研究包.json',JSON.stringify({format:'lvxing-research-bundle',version:1,exportedAt:new Date().toISOString(),project:p},null,2));},
 'run-tests':()=>{const start=performance.now();latestChecks=[...C.tests(),...R.tests()];record('本版功能自检',{suite:'studio-v1.1',count:latestChecks.length},{checks:latestChecks},start);render();toast(latestChecks.filter(t=>t.passed).length+' / '+latestChecks.length+' 检查通过');},
 'export-tests':()=>{if(!latestChecks.length)throw Error('请先运行检查');download('绿行智研_功能检查.json',JSON.stringify({version:C.version,checks:latestChecks,note:'规则单元检查，不是大模型评测'},null,2));},
 'new-project':()=>projectModal(false),'edit-project':()=>projectModal(true),
 'save-project':el=>{let profile={title:$('#pTitle').value.trim(),city:$('#pCity').value.trim(),company:$('#pCompany').value.trim(),question:$('#pQuestion').value.trim()};const sample=$('#pSample')?.checked;if(!sample&&Object.values(profile).some(x=>!x))throw Error('请填写研究名称、城市、公司与问题');if(el.dataset.edit==='true'){project().profile=profile;}else{if(state.projects.length>=20)throw Error('工作区最多保留20个研究，可先导出备份');const p=D.seed();if(!sample){p.profile=profile;p.docs=[];p.facts=[];p.policy={measure:'',effect:'',gap:'',sourceId:'',confirmed:false};p.financeInputs.baseline=0;}p.id=uid();state.projects.push(p);state.active=p.id;}currentReport='';persist();closeDialog();go('overview');toast('研究范围已保存');},
 'projects':()=>modal('切换研究',state.projects.map(p=>`<button class="query-result" data-action="switch-project" data-id="${p.id}"><b>${esc(p.profile.title)} ${state.active===p.id?'✓':''}</b><small>${esc(p.profile.city)} · ${esc(p.profile.company)} · ${p.docs.length} 份资料 · ${p.runs.length} 条记录</small></button>`).join(''),btn('新建研究','new-project','outline')),
 'switch-project':el=>{if(busy)throw Error('正在解析文件，请等待完成后切换');state.active=el.dataset.id;currentReport='';persist();closeDialog();go('overview');},
 'settings':()=>modal('工作区设置',`<div class="alert green">研究资料与计算快照保存在当前浏览器的 IndexedDB 中，不上传到远程数据库。换设备或清理浏览器前，请导出工作区备份。</div><div class="risk-list"><div class="risk-item"><span>01</span><div><b>工作区备份</b><br>包含全部研究、导入文本、参数和报告版本。<div class="actions" style="margin-top:10px">${btn('导出备份','backup','outline small')}${btn('导入备份 / 研究包','restore','outline small')}</div></div></div><div class="risk-item"><span>02</span><div><b>展示模式</b><br>压缩侧栏并隐藏页脚，方便后续录制产品演示。<div class="actions" style="margin-top:10px">${btn(document.body.classList.contains('presentation')?'退出展示模式':'进入展示模式','presentation','outline small')}</div></div></div></div><p class="hint" style="margin-top:20px">当前为浏览器本地分析产品，不含远程账号、实时行情、OCR或外部模型服务。移动端没有改动。</p>`),
 'backup':()=>download('绿行智研_工作区备份.json',JSON.stringify({format:'lvxing-workspace',version:1,exportedAt:new Date().toISOString(),state},null,2)),
 'restore':()=>$('#backupImport').click(),
 'presentation':()=>{document.body.classList.toggle('presentation');state.presentation=document.body.classList.contains('presentation');persist();closeDialog();toast(state.presentation?'已进入展示模式':'已退出展示模式');},
 'history':()=>{const runs=project().runs;modal('当前研究的运行记录',runs.map(r=>`<div class="candidate"><div class="row between"><b>${esc(r.kind)}</b>${tag(fmt(r.durationMs,1)+' ms')}</div><p>${time(r.createdAt)} · ${r.inputHash}</p><details><summary class="hint" style="cursor:pointer">查看输入与结果</summary><pre class="source-text" style="max-height:200px;font-size:10px">${esc(JSON.stringify({inputs:r.inputs,result:r.result},null,2))}</pre></details></div>`).join('')||empty('还没有运行记录','执行一次计算后将记录实际输入与结果。'),btn('导出研究包','export-bundle','outline'));},
 'guide':()=>{guideStep=0;go(guide[0][0]);},'guide-next':()=>{guideStep++;if(guideStep>=guide.length){guideStep=-1;renderGuide();toast('导览完成。确认产品后，再按这一版本制作操作视频。');}else go(guide[guideStep][0]);},'guide-close':()=>{guideStep=-1;renderGuide();},
 'help':()=>modal('从资料到报告，怎样走一遍？',`<div class="risk-list">${guide.map((g,i)=>`<div class="risk-item"><span>${i+1}</span><div><b>${g[1]}</b><br>${g[2]}</div></div>`).join('')}</div><div class="alert">文档解析与检索已实现，但没有调用外部大语言模型。图表对应当前计算代码，不是生产业务数据。移动端仍可从左下角独立打开。</div>`,btn('开始产品导览','start-guide')),
 'start-guide':()=>{closeDialog();guideStep=0;go(guide[0][0]);}
};
document.addEventListener('click',async e=>{const routeEl=e.target.closest('[data-route]');if(routeEl){go(routeEl.dataset.route);return;}const el=e.target.closest('[data-action]');if(!el)return;const handler=actions[el.dataset.action];if(!handler)return;try{if(el.dataset.action==='source'&&$('#dialog').open)closeDialog();await handler(el);}catch(error){toast(error.message||'操作失败，请重试',true);const target=$('#financeStatus')||$('#carbonStatus')||$('#behaviorStatus');if(target){target.classList.add('dirty');target.textContent=error.message;}}});
$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer'))$('#drawer').hidden=true;});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();actions.search();}if(e.key==='Escape')$('#drawer').hidden=true;});
$('#fileImport').addEventListener('change',e=>importFiles([...e.target.files]).catch(e=>{busy=false;toast(e.message,true);}));
$('#csvImport').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('出行CSV上限2MB');const rows=C.carbonCSV(await file.text());if(rows.length>100)throw Error('最多100条替代方式，请先汇总');project().carbonRows=rows;project().carbonResult=null;v2?.invalidateCarbon();persist();render();toast('已导入 '+rows.length+' 条出行记录，请计算并保存');}catch(e){toast(e.message,true);}finally{$('#csvImport').value='';}});
function validateProject(p){if(!p||!p.profile||!Array.isArray(p.docs)||!Array.isArray(p.facts)||!Array.isArray(p.runs)||!Array.isArray(p.reports)||!p.policy)throw Error('研究包结构不完整');for(const key of ['title','city','company','question'])if(typeof p.profile[key]!=='string')throw Error('研究信息格式错误');if(p.docs.length>60||p.facts.length>1000||p.runs.length>80||p.reports.length>20)throw Error('导入内容超过工作区限制');for(const d of p.docs){if(!/^[\w-]+$/.test(d.id)||typeof d.title!=='string'||typeof d.kind!=='string'||!Array.isArray(d.pages)||d.pages.some(x=>!Number.isInteger(x.page)||typeof x.text!=='string'))throw Error('资料格式错误');}for(const f of p.facts)if(!/^[\w-]+$/.test(f.id))throw Error('事实字段编号格式错误');for(const r of p.reports)if(!/^[\w-]+$/.test(r.id)||typeof r.text!=='string')throw Error('报告格式错误');C.carbon(p.carbonRows);C.behavior(p.behaviorInputs);C.finance(p.financeInputs);for(const k of ['measure','effect','gap'])if(typeof p.policy[k]!=='string')throw Error('政策字段格式错误');R.validate(p);p.id=uid();p.profile.title+='（导入）';return p;}
$('#backupImport').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>40*1024*1024)throw Error('备份超过40MB');const data=JSON.parse(await file.text());let ps;if(data.format==='lvxing-workspace')ps=data.state?.projects;else if(data.format==='lvxing-research-bundle')ps=[data.project];else throw Error('不是本产品导出的备份或研究包');if(!Array.isArray(ps)||ps.length+state.projects.length>20)throw Error('导入后研究数量不可超过20');const checked=ps.map(validateProject);state.projects.push(...checked);await persist();closeDialog();render();toast('已新增导入 '+checked.length+' 项研究，原有研究未覆盖');}catch(e){toast(e.message||'备份格式错误',true);}finally{$('#backupImport').value='';}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(id!==route){route=routes.some(r=>r[0]===id)?id:'overview';render();window.scrollTo(0,0);}});
async function init(){try{db=await openDB();state=await readDB();}catch(e){toast('本地存储不可用，本次数据无法持久保存，请及时导出',true);}if(!state||state.version!==1||!state.projects?.length){const seed=D.seed();state={version:1,active:seed.id,projects:[seed],presentation:false};if(db)await persist();}if(state.caseRevision!==2){state.projects.forEach(D.correctCasePages);state.caseRevision=2;if(db)await persist();}state.projects.forEach(R.normalize);const {createResearchStudio}=await import('./studio-v2.mjs?v=1.1.0');v2=createResearchStudio({project,getState:()=>state,route:()=>route,actions,render,persist,record,go,modal,closeDialog,toast,download,btn,tag,input,textfield,textarea,esc,fmt,uid,readFinance,readBehavior,setReport:t=>{currentReport=t;},getReport:()=>currentReport});$('#saveState').textContent=db?'已保存到此浏览器':'临时会话，请导出';if(state.presentation)document.body.classList.add('presentation');route=routes.some(r=>r[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();}
init().catch(e=>{$('#main').innerHTML=empty('工作区未能打开',esc(e.message));});
